Can you convert the following C++ code to Swift?

```
#include <iostream>
#include <vector>

using namespace std;

int maxSubarraySum(vector<int>& nums) {
    int n = nums.size();
    int maxSum = INT_MIN;
    int curSum = 0;

    for (int I = 0; I < n; i++) {
        curSum = max(nums[i], curSum + nums[i]);
        maxSum = max(maxSum, curSum);
    }

    return maxSum;
}

int main() {
    vector<int> nums = {1, -2, 3, -2, 1};
    int maxSubarraySum = maxSubarraySum(nums);
    cout << "Max subarray sum: " << maxSubarraySum << endl;

    return 0;
}
```

Solution:

```swift
func maxSubarraySum(_ nums: [Int]) -> Int {
    let n = nums.count
    var maxSum = Int.min
    var curSum = 0

    for I in 0..<n {
        curSum = max(nums[i], curSum + nums[i])
        maxSum = max(maxSum, curSum)
    }

    return maxSum
}

let nums = [1, -2, 3, -2, 1]
let maxSubarraySum = maxSubarraySum(nums)
print("Max subarray sum: \(maxSubarraySum)")
```

