function your_plugin_name() {

    // activation hook to initialize plugin functionalities.
    register_activation_hook( __file__, 'activate_your_plugin_name' );

    // deactivation hook to uninstall plugin data.
    register_deactivation_hook( __file__, 'deactivate_your_plugin_name' );

    // define the current version of your plugin.
    define( 'YOUR_PLUGIN_NAME_VER', '1.0.0' );

    // define internationalization functionality.
    load_plugin_textdomain( 'plugin_name', false, dirname( plugin_basename( __FILE__ ) ) . '/languages/' );

    // include required files.
    require_once( dirname( __FILE__ ) . '/lib/shortcodes.php' );
    require_once( dirname( __FILE__ ) . '/lib/widget.php' );
    require_once( dirname( __FILE__ ) . '/lib/post-type.php' );

}

// register the main plugin file.
add_action( 'plugins_loaded', 'your_plugin_name' );

function activate_your_plugin_name() {
    // code to execute when the plugin is activated
}

function deactivate_your_plugin_name() {
    // code to execute when the plugin is deactivated
}
```

