import breeze.linalg.{DenseVector, eigen}
import breeze.numerics.pow

// Define a function to perform dimensionality reduction and feature selection
def extractImportantFeatures(featureMatrix: Array[Array[Double]]): Seq[Int] = {
  val reducedMatrix = PCA(featureMatrix)

  // Extract the most important original features (columns) from the reduced matrix
  val featureImportances = calculateFeatureImportances(reducedMatrix, featureMatrix)
  featureImportances.toList.sortBy(-_._2).take(5).map(_._1)
}

// Define a function to calculate feature importances using e.g. Linear regression
def calculateFeatureImportances(reducedMatrix: Array[Array[Double]], origMatrix: Array[Array[Double]]): Map[Int, Double] = {
  import breeze.stats.{corr, mean}

  val desiredDimension = reducedMatrix.map(_.nonEmpty).transpose.reduce(_ && _)

  val featureImportances = for (i <- desiredDimension.indices) yield {
    val reducedFeature = DenseVector(reducedMatrix.map(_(i)))
    val originalFeature = DenseVector(origMatrix.map(row => row(i)))

    val regression = breeze.stats.linearRegression(reducedFeature, originalFeature)

    // Use the R-squared coefficient as feature importance
    (i, pow(corr(reducedFeature, originalFeature), 2) * pow(regression.r2, 2))
  }.toMap
}

// Apply feature selection to each cluster and compute mean important features
