#include <curl/curl.h>

using namespace std;

struct CallbackData {
    stringstream *stream;
    size_t *totalSize;
};

static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userPtr) {
    CallbackData *data = (CallbackData*)userPtr;
    data->stream->write(static_cast<char*>(contents), size * nmemb);
    data->totalSize += size * nmemb;
    return size * nmemb;
}

int main() {
