   ```typescript
   import express, { Request, Response } from 'express';

   const app = express();

   function logApiMiddleware(req: Request, res: Response, next: express.NextFunction) {
     if (req.originalUrl.startsWith('/api')) {
       console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
     }
     next();
   }

   app.use(logMiddleware);
   app.use(logApiMiddleware);

   app.get('/', (req: Request, res: Response) => {
     res.send('Hello world!');
   });

   app.get('/api/users', (req: Request, res: Response) => {
     res.send('API: List of users');
   });

   const port = process.env.PORT || 3000;
   app.listen(port, () => {
     console.log(`Server running on http://localhost:${port}`);
   });
   ```

   We have added a new middleware function called `logApiMiddleware` that logs information only if the request URL starts with `/api`. Then we call `app.use()` again to register this middleware, ensuring that both middleware run for every incoming request. 3. You can also create a generic middleware that can be applied to various routes. For example, let's create a middleware that adds a custom header to the response:

   ```typescript
   import express, { Request, Response } from 'express';

   const app = express();

   function addHeaderMiddleware(req: Request, res: Response, next: express.NextFunction) {
     res.setHeader('X-My-Header', 'Hello from middleware!');
     next();
   }

   app.use(logMiddleware);
   app.use(logApiMiddleware);
   app.use(addHeaderMiddleware); // apply this middleware to all routes

   app.get('/', (req: Request, res: Response) => {
     res.send('Hello world!');
   });

   app.get('/api/users', (req: Request, Response) => {
     res.send('API: List of users');
