import express from 'express';

// Création d'un serveur Express
const app = express();

// Route GET
app.get('/', (req: express.Request, res: express.Response) => {
  res.send('Hello World!');
});

// Route POST avec validation des paramètres envoyés dans le corps de la requête
interface MyData {
  id: number;
  name: string;
}

app.post('/api/data', (req: express.Request, res: express.Response) => {
  // On désérialise le corps de la requête dans la variable myData
  const { id, name }: MyData = req.body;

  // Vérification que les données ont bien été envoyées avec la requête POST
  if (!id || !name) {
    res.status(400).send('Bad request');
    return;
  }

  // Log de la requête
  console.log(`POST /api/data - ID: ${id}, Name: ${name}`);

  res.send('Data received successfully');
});

// Route PUT avec validation des paramètres envoyés dans l'URI
app.put('/api/users/:id', (req: express.Request, res: express.Response) => {
  // On récupère l'ID passé dans l'URI
  const userId = Number(req.params.id);

  // Vérification que l'ID est bien un nombre entier
  if (isNaN(userId) || userId <= 0) {
    res.status(400).send('Bad request');
    return;
  }

  // Log de la requête
  console.log(`PUT /api/users/${userId}`);

  res.send('User updated successfully');
});

// Route DELETE
app.delete('/api/users/:id', (req: express.Request, res: express.Response) => {
  // On récupère l'ID passé dans l'URI
  const userId = Number(req.params.id);

  // Vérification que l'ID est bien un nombre entier
  if (isNaN(userId) || userId <= 0) {
    res.status(400).send('Bad request');
    return;
  }

  // Log de la requête
  console.log(`DELETE /api/users/${userId}`);

  res.send('User deleted successfully');
});

// Ecouteur sur le port 3000
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
```

