function hasLongestWordWithSevenOrMoreLetters(str) {
  // Remove all non-alphanumeric characters (i.e., punctuation and underscores) and split the string into an array of words
  const wordsArray = str.replace(/[^0-9a-z]/gi, '').toLowerCase().split(' ');

  // Find the length of the longest word
